const traced = await eda.pcb_MathPolygon.traceImage({ imageBlob, quality: 'high' });
if (!traced) {
  console.log('空描摹：无图可放置');
  return;
}

const ok = await eda.pcb_ImageTool.startPlaceVectorImage({
  path: traced.path,
  width: 50,
  height: 30,
  unit: 'mm',
});
console.log('矢量放置已触发：', ok);
